import sys

def main():
    data = sys.stdin.read().split()
    m, die, start, last = (int(x) for x in data[:4])
    tele = {}
    for i in range(m):
        tele[int(data[4 + 2 * i])] = int(data[5 + 2 * i])
    if start == last:
        print('true')
        return
    nxt = list(range(last + 3))

    def find(x):
        root = x
        while nxt[root] != root:
            root = nxt[root]
        while nxt[x] != root:
            nxt[x], x = root, nxt[x]
        return root

    seen = {start}
    queue = [start]
    qi = 0
    while qi < len(queue):
        p = queue[qi]
        qi += 1
        hi = min(p + die, last)
        x = find(p + 1)
        while x <= hi:
            if x == last:
                print('true')
                return
            nxt[x] = x + 1
            e = tele.get(x, x)
            if e == last:
                print('true')
                return
            if e not in seen:
                seen.add(e)
                queue.append(e)
            x = find(x + 1)
    print('false')

main()

